/* Layout for net packet:
 *
 * | <-------------- NETPKT_BUFLEN ---------------> |
 * +---------------------+-------------------+------+      +-------------+
 * | reserved for driver |       data        | free | ---> | next netpkt |
 * +---------------------+-------------------+------+      +-------------+
 * |                     | <--- datalen ---> |
 * ^base                 ^data
 */

/* Layout for linked net packet, you can get list of (data, len) by
 * netpkt_to_iov() interface:
 *
 *            | <----------- datalen = sum(len) ------------> |
 * +----------+-----------+     +-----------+     +-----------+------+
 * | reserved |   data    | --> |   data    | --> |   data    | free |
 * +----------+-----------+     +-----------+     +-----------+------+
 * |          | <- len -> |     | <- len -> |     | <- len -> |
 * ^base      ^data             ^data             ^data
 */

#define NETPKT_BUFLEN   CONFIG_IOB_BUFSIZE
#define NETPKT_BUFNUM   CONFIG_IOB_NBUFFERS

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* We use IOB as our buffer now, we may change to some other structure when
 * needed, so define a type netpkt_t for lower half.
 * TODO: Provide interface of its queue, maybe a simple wrapper of iob_queue.
 */

typedef struct iob_s netpkt_t;
typedef struct iob_queue_s netpkt_queue_t;

enum netpkt_type_e
{
  NETPKT_TX,
  NETPKT_RX,
  NETPKT_TYPENUM
};

enum netdev_rx_e
{
  NETDEV_RX_WORK,      /* Use work queue thread */
  NETDEV_RX_DIRECT,    /* Directly based on the current thread */
  NETDEV_RX_THREAD,    /* Upper half dedicated thread */
  NETDEV_RX_THREAD_RSS /* RSS mode, upper half thread */
};

/* This structure is the generic form of state structure used by lower half
 * netdev driver. This state structure is passed to the netdev driver when
 * the driver is initialized. Then, on subsequent callbacks into the lower
 * half netdev logic, this structure is provided so that the netdev logic can
 * maintain state information.
 *
 * Normally that netdev logic will have its own, custom state structure
 * that is simply cast to struct netdev_lowerhalf_s. In order to perform such
 * casts, the initial fields of the custom state structure match the initial
 * fields of the following generic netdev state structure.
 */

struct netdev_ops_s;
struct wireless_ops_s;
struct ethtool_ops_s;

struct netdev_lowerhalf_s
{
  FAR const struct netdev_ops_s *ops;

 ****************************************************************************/

int netdev_lower_quota_load(FAR struct netdev_lowerhalf_s *dev,
                            enum netpkt_type_e type)
{
  return atomic_read(&dev->quota_ptr[type]);
}

/****************************************************************************
 * Name: netdev_lower_vlan_add
 *
 * Description:
 *   Add a VLAN device to the network device.
 *
 * Input Parameters:
 *   dev  - The lower half device driver structure
 *   vid  - VLAN ID
 *   vlan - The VLAN device to add
 *
 * Returned Value:
 *   0:Success; negated errno on failure
 *
 ****************************************************************************/

#ifdef CONFIG_NET_VLAN
int netdev_lower_vlan_add(FAR struct netdev_lowerhalf_s *dev, uint16_t vid,
                          FAR struct netdev_lowerhalf_s *vlan)
{
  FAR struct netdev_upperhalf_s  *upper = dev->netdev.d_private;
  FAR struct netdev_vlan_entry_s *entry = NULL;
  int i;

  for (i = 0; i < CONFIG_NET_VLAN_COUNT; i++)
    {
      if (upper->vlan[i].vid == vid)
        {
          return -EEXIST;
        }

      if (upper->vlan[i].vid == 0 && entry == NULL)
        {
          entry = &upper->vlan[i];
        }
    }

  if (entry)
    {
      entry->vid = vid;
      entry->dev = vlan;
      return OK;
    }

  return -ENOMEM;
}

/****************************************************************************
 * Name: netdev_lower_vlan_del
 *
 * Description:
 *   Delete a VLAN device from the network device.
 *
 * Input Parameters:
 *   dev - The lower half device driver structure
 *   vid - VLAN ID
 *
 * Returned Value:
 *   0:Success; negated errno on failure
 *
 ****************************************************************************/

int netdev_lower_vlan_del(FAR struct netdev_lowerhalf_s *dev, uint16_t vid)
{
  FAR struct netdev_upperhalf_s *upper = dev->netdev.d_private;
  int i;

  for (i = 0; i < CONFIG_NET_VLAN_COUNT; i++)
    {
      if (upper->vlan[i].vid == vid)
        {
          upper->vlan[i].vid = 0;
          upper->vlan[i].dev = NULL;
          return OK;
        }
    }

  return -ENOENT;
}
