 * Name: ethloop_monitor
 *
 * Description:
 *   Notice a run that has stopped moving.  It only reports it: the
 *   connection's own progress watchdog is what abandons it, so that the
 *   socket is closed from the thread that owns it.
 *
 ****************************************************************************/

static void *ethloop_monitor(void *arg)
{
  int announced = 0;

  UNUSED(arg);

  while (!g_stop)
    {
      usleep(1000000);

      if (!g_conn_active || g_stop || g_last_progress_ns == 0)
        {
          announced = 0;
          continue;
        }

      if (ethloop_now_ns() - g_last_progress_ns <
          ETHLOOP_HANG_MS * ETHLOOP_NS_PER_MS)
        {
          continue;
        }

      if (announced == 0)
        {
          printf("ethloop: HANG: no byte moved for %d ms: tx %llu B, "
                 "rx %llu B, iob free %d, connections %d\n",
                 ETHLOOP_HANG_MS, (unsigned long long)g_dir[0].tx_bytes,
                 (unsigned long long)g_dir[0].rx_bytes, iob_navail(false),
                 g_connections);
        }
      else if ((announced % 10) == 0)
        {
          printf("ethloop: still hung: tx %llu B rx %llu B iob %d\n",
                 (unsigned long long)g_dir[0].tx_bytes,
                 (unsigned long long)g_dir[0].rx_bytes, iob_navail(false));
        }

      announced++;
    }

  return NULL;
}

