        {
          d->min_mbit_x10 = mbit_x10;
        }

      if (mbit_x10 > d->max_mbit_x10)
        {
          d->max_mbit_x10 = mbit_x10;
        }
    }

  printf("\n");

  /* Five seconds without a byte in either direction is a wedged connection,
   * not a slow one.  Failing it here lets the client drop it and reconnect.
   */

  if (!g_stop && conn != NULL && !conn->failed && g_last_progress_ns != 0 &&
      now - g_last_progress_ns > ETHLOOP_PROGRESS_MS * ETHLOOP_NS_PER_MS)
    {
      conn->failed = true;
      conn->err = ETIMEDOUT;
      conn->where = "progress";
      printf("ethloop: no byte moved for %d s, abandoning the connection\n",
             ETHLOOP_PROGRESS_MS / 1000);
    }

  g_last_report_ns = now;
}

