/****************************************************************************
 * Name: gm_ifdown
 *
 * Description:
 *   Take the port down.  The whole teardown runs under the per-device network
 *   lock, which is what serializes it against gm_link_work(): see the note
 *   there.  netdev_ifdown() already holds that lock when it reaches here
 *   through SIOCSIFFLAGS, and the recursive rmutex lets this function take it
 *   again for the callers that do not -- so a link worker that is in the
 *   middle of its PHY poll either finishes before the lock is taken, or runs
 *   after it and finds started == false.
 *
 ****************************************************************************/

static int gm_ifdown(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)dev;
  bool carrier;
  int ret;

  if (!priv->started)
    {
      return OK;
    }

  netdev_lock(&priv->dev.netdev);

  priv->started = false;

  work_cancel(LPWORK, &priv->linkwork);
  work_cancel(LPWORK, &priv->rxretry);

  up_disable_irq(priv->irq);
  irq_detach(priv->irq);

  /* The rings are released only once both DMA directions have been proven
   * stopped: while the engine can still read a descriptor or a buffer, that
   * memory has to stay.  A stop that timed out is retried through a port
   * reset, which takes the engine down even when its own stop never
   * completed; only if that also fails are the rings kept -- a leak that a
   * reboot clears, against a DMA that would otherwise keep writing into
   * buffers the stack has already reused.
   */

  ret = gm_mac_stop(priv);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "gmac%d: DMA did not stop (%d); resetting the port before "
             "releasing the rings\n",
             priv->intf, ret);

      ret = gm_reset(priv);
      if (ret < 0)
        {
          syslog(LOG_ERR,
                 "gmac%d: reset failed too (%d); the rings and their buffers "
                 "are kept, and this port needs a reboot\n",
                 priv->intf, ret);
          netdev_unlock(&priv->dev.netdev);
          return ret;
        }
    }

  gm_rings_free(priv);

  carrier = priv->carrier;
  priv->carrier = false;

  if (carrier)
    {
      netdev_lower_carrier_off(dev);
    }

  netdev_unlock(&priv->dev.netdev);
  return OK;
}

